const TEST_MODE = true;
const TEST_EMAIL = 'kyisinthant123mdy@gmail.com';
const MODEL = 'gpt-5-mini';

const rows = $input.all().map((item, index) => {
  const source = item.json;
  const hotel = String(source.brandname ?? '').trim();
  const revenue = Number(source.revenue);
  const orders = Number(source.Order);
  const ownerEmail = String(source['Boss Gmail'] ?? '').trim();
  if (!hotel || !Number.isFinite(revenue) || revenue < 0 || !Number.isFinite(orders) || orders < 0 || !ownerEmail) {
    throw new Error(`Invalid data in input row ${index + 2}`);
  }
  return { hotel, revenue, orders, owner_email: ownerEmail };
});
if (!rows.length) throw new Error('No hotel rows were returned');

const median = values => {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
};
const medianRevenue = median(rows.map(row => row.revenue));
const medianOrders = median(rows.map(row => row.orders));
const now = new Date();
const mondayOffset = (now.getDay() + 6) % 7;
const thisMonday = new Date(now);
thisMonday.setDate(now.getDate() - mondayOffset);
const weekEnd = new Date(thisMonday);
weekEnd.setDate(thisMonday.getDate() - 1);
const weekStart = new Date(weekEnd);
weekStart.setDate(weekEnd.getDate() - 6);
const isoDate = date => date.toISOString().slice(0, 10);
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

return rows.map(row => {
  const doingWell = row.revenue >= medianRevenue && row.orders >= medianOrders;
  const noActivity = row.revenue === 0 && row.orders === 0;
  const status = doingWell ? 'Doing well' : 'Needs improvement';
  const week_start = isoDate(weekStart);
  const week_end = isoDate(weekEnd);
  let lead;
  let action;
  if (doingWell) {
    lead = 'You finished at or above the hotel group median on both revenue and bookings.';
    action = 'Keep the campaigns and availability settings that supported this result, and review the strongest booking sources for repeatable wins.';
  } else if (noActivity) {
    lead = 'No revenue or bookings were recorded for the week.';
    action = 'First confirm that the data feed is complete. If it is, review availability, pricing, and active sales channels.';
  } else {
    const weak = [];
    if (row.revenue < medianRevenue) weak.push('revenue');
    if (row.orders < medianOrders) weak.push('bookings');
    lead = `This week, ${weak.join(' and ')} finished below the hotel group median.`;
    action = 'Review availability and pricing for the coming two weeks, then focus promotions on the channels that produced the most recent bookings.';
  }
  const hotelHtml = escapeHtml(row.hotel);
  const fallback_subject = `Weekly performance summary - ${row.hotel}`;
  const fallback_html = `<p>Hello ${hotelHtml} team,</p><p>Here is your performance summary for ${week_start} to ${week_end}. You recorded <strong>${row.orders.toLocaleString('en-US')} bookings</strong> and <strong>${row.revenue.toLocaleString('en-US')}</strong> in revenue.</p><p>${lead} The comparison benchmark was ${medianOrders.toLocaleString('en-US')} bookings and ${medianRevenue.toLocaleString('en-US')} in revenue.</p><p><strong>Recommended next step:</strong> ${action}</p><p>Best regards,<br>Hotel Partnerships Team</p>`;
  const facts = { ...row, status, no_activity: noActivity, median_revenue: medianRevenue, median_orders: medianOrders, week_start, week_end };
  const api_payload = {
    model: MODEL,
    store: false,
    instructions: 'Write a concise weekly hotel performance email. Use only the supplied facts. Do not invent causes, targets, percentages, or comparisons. Be supportive and specific, include one practical next step, and produce safe simple HTML with no links or images.',
    input: JSON.stringify(facts),
    text: {
      format: {
        type: 'json_schema',
        name: 'hotel_weekly_email',
        strict: true,
        schema: {
          type: 'object',
          properties: { subject: { type: 'string' }, html_body: { type: 'string' } },
          required: ['subject', 'html_body'],
          additionalProperties: false
        }
      }
    }
  };
  return { json: { ...facts, recipient: TEST_MODE ? TEST_EMAIL : row.owner_email, test_mode: TEST_MODE, fallback_subject, fallback_html, api_payload } };
});

const generated = $input.all();
const sourceRows = $('Calculate benchmarks').all();
return generated.map((item, index) => {
  const source = sourceRows[index].json;
  let outputText = item.json.output_text;
  if (!outputText && Array.isArray(item.json.output)) {
    for (const output of item.json.output) {
      for (const content of output.content ?? []) {
        if (content.type === 'output_text') outputText = content.text;
      }
    }
  }
  let subject = source.fallback_subject;
  let html_body = source.fallback_html;
  let message_source = 'deterministic_fallback';
  try {
    const parsed = JSON.parse(outputText ?? '{}');
    if (typeof parsed.subject === 'string' && typeof parsed.html_body === 'string') {
      subject = parsed.subject;
      html_body = parsed.html_body;
      message_source = 'openai';
    }
  } catch (error) {
    // Fallback is intentional so one model error does not stop the batch.
  }
  return { json: { ...source, subject, html_body, message_source } };
});
